import pytest
from gspread.utils import ValueRenderOption


def test_accepted_kwargs_and_filter_dict_values_removed():
    """Test that accepted_kwargs and filter_dict_values have been successfully removed
    from gspread.utils, as they are obsolete in v6.0.0.
    """
    with pytest.raises(ImportError):
        from gspread.utils import accepted_kwargs  # type: ignore

    with pytest.raises(ImportError):
        from gspread.utils import filter_dict_values  # type: ignore


def test_worksheet_methods_accept_enums_directly(monkeypatch):
    """Test that worksheet methods (like get, get_values, update, etc.) accept explicit
    keyword arguments and Enums (or values like ValueRenderOption) directly without
    raising unexpected keyword argument errors from accepted_kwargs.
    """
    from gspread.worksheet import Worksheet

    # Mock client and fetch_sheet_metadata
    class MockClient:
        def __init__(self):
            self.last_params = None
            self.last_body = None

        def values_get(self, spreadsheet_id, range_name, params=None):
            self.last_params = params
            return {"range": range_name, "majorDimension": "ROWS", "values": [["1"]]}

        def values_update(self, spreadsheet_id, range_name, params=None, body=None):
            self.last_params = params
            self.last_body = body
            return {}

        def fetch_sheet_metadata(self, spreadsheet_id):
            return {"sheets": [{"properties": {"sheetId": 0, "title": "Sheet1"}}]}

    client = MockClient()
    ws = Worksheet("dummy_id", client, {"sheetId": 0, "title": "Sheet1"})

    # Test get with ValueRenderOption enum value or string
    ws.get("A1", value_render_option=ValueRenderOption.unformatted, major_dimension="ROWS")
    assert client.last_params == {
        "majorDimension": "ROWS",
        "valueRenderOption": ValueRenderOption.unformatted,
        "dateTimeRenderOption": None,
    }

    # Test update with explicit args
    ws.update("A1", "test", raw=False, value_input_option=None)
    assert client.last_params == {
        "valueInputOption": "USER_ENTERED",
        "includeValuesInResponse": None,
        "responseValueRenderOption": None,
        "responseDateTimeRenderOption": None,
    }
    assert client.last_body == {
        "values": [["test"]],
        "majorDimension": None,
    }

import pytest
from gspread.utils import Dimension, ValueRenderOption, DateTimeOption, ValueInputOption
from gspread.worksheet import Worksheet


class DummyClient:
    def __init__(self):
        self.values_get_called_with = None
        self.values_batch_get_called_with = None
        self.values_update_called_with = None
        self.values_batch_update_called_with = None

    def values_get(self, spreadsheet_id, range_name, params=None):
        self.values_get_called_with = {
            "spreadsheet_id": spreadsheet_id,
            "range_name": range_name,
            "params": params,
        }
        return {
            "range": range_name,
            "majorDimension": "ROWS",
            "values": [["1", "2"], ["3", "4"]],
        }

    def values_batch_get(self, spreadsheet_id, ranges, params=None):
        self.values_batch_get_called_with = {
            "spreadsheet_id": spreadsheet_id,
            "ranges": ranges,
            "params": params,
        }
        return {
            "valueRanges": [
                {
                    "range": r,
                    "majorDimension": "ROWS",
                    "values": [["1"]],
                }
                for r in ranges
            ]
        }

    def values_update(self, spreadsheet_id, range_name, params=None, body=None):
        self.values_update_called_with = {
            "spreadsheet_id": spreadsheet_id,
            "range_name": range_name,
            "params": params,
            "body": body,
        }
        return {"updatedCells": 1}

    def values_batch_update(self, spreadsheet_id, body=None):
        self.values_batch_update_called_with = {
            "spreadsheet_id": spreadsheet_id,
            "body": body,
        }
        return {"totalUpdatedCells": 1}

    def fetch_sheet_metadata(self, spreadsheet_id=None, params=None):
        return {
            "sheets": [
                {
                    "properties": {
                        "sheetId": 0,
                        "title": "Sheet1",
                    }
                }
            ]
        }


def test_accepted_kwargs_and_filter_dict_values_removed():
    """Verify that accepted_kwargs and filter_dict_values are removed from gspread.utils."""
    import gspread.utils as utils

    assert not hasattr(utils, "accepted_kwargs")
    assert not hasattr(utils, "filter_dict_values")


def test_worksheet_methods_with_explicit_none_parameters():
    """Test that worksheet methods accept parameters directly (including None)
    without using the old accepted_kwargs decorator or filter_dict_values helper,
    and pass them correctly to the client API.
    """
    client = DummyClient()
    properties = {"sheetId": 0, "title": "Sheet1", "gridProperties": {"rowCount": 10, "columnCount": 10}}
    ws = Worksheet("dummy_id", client, properties)

    # Test get and get_values with explicit Enums and None values
    ws.get(
        "A1:B2",
        major_dimension=Dimension.rows,
        value_render_option=ValueRenderOption.unformatted,
        date_time_render_option=None,
    )

    assert client.values_get_called_with["params"] == {
        "majorDimension": Dimension.rows,
        "valueRenderOption": ValueRenderOption.unformatted,
    }

    ws.get_values(
        "A1:B2",
        major_dimension=Dimension.cols,
        value_render_option=ValueRenderOption.formula,
        date_time_render_option=DateTimeOption.serial_number,
    )
    assert client.values_get_called_with["params"] == {
        "majorDimension": Dimension.cols,
        "valueRenderOption": ValueRenderOption.formula,
        "dateTimeRenderOption": DateTimeOption.serial_number,
    }

    # Test batch_get
    ws.batch_get(
        ["A1:B2", "C1:D2"],
        major_dimension=Dimension.rows,
        value_render_option=None,
        date_time_render_option=None,
    )
    assert client.values_batch_get_called_with["params"] == {
        "majorDimension": Dimension.rows,
    }

    # Test update
    ws.update(
        "A1:B2",
        values=[[1, 2], [3, 4]],
        raw=False,
        major_dimension=Dimension.rows,
        value_input_option=None,
        include_values_in_response=True,
        response_value_render_option=ValueRenderOption.formatted,
        response_date_time_render_option=None,
    )
    assert client.values_update_called_with["params"] == {
        "valueInputOption": ValueInputOption.user_entered,
        "includeValuesInResponse": True,
        "responseValueRenderOption": ValueRenderOption.formatted,
    }
    assert client.values_update_called_with["body"] == {
        "values": [[1, 2], [3, 4]],
        "majorDimension": Dimension.rows,
    }

    # Test batch_update
    ws.batch_update(
        data=[{"range": "A1:B2", "values": [[1]]}],
        raw=True,
        value_input_option=None,
        include_values_in_response=None,
        response_value_render_option=None,
        response_date_time_render_option=None,
    )
    assert client.values_batch_update_called_with["body"] == {
        "valueInputOption": ValueInputOption.raw,
        "data": [{"range": "'Sheet1'!A1:B2", "values": [[1]]}],
    }

