import pytest
import jwt
from jwt.api_jwt import PyJWT
from jwt.exceptions import InvalidAudienceError, MissingRequiredClaimError


@pytest.fixture
def jwt_instance():
    return PyJWT()


def test_decode_jwt_with_aud_null_and_no_audience_argument(jwt_instance):
    """
    Test that when a JWT contains `{"aud": null}` and no audience argument is passed to decode(),
    it is treated the same as unspecified (i.e. ignored without raising an error).
    """
    payload = {"some": "payload", "aud": None}

    token = jwt_instance.encode(payload, "secret", algorithm="HS256")

    # Decode without passing audience argument. Should succeed and return payload with aud: None.
    decoded = jwt_instance.decode(token, "secret", algorithms=["HS256"])
    assert decoded == {"some": "payload", "aud": None}


def test_decode_jwt_with_aud_null_and_audience_argument_raises_error(jwt_instance):
    """
    Test that when a JWT contains `{"aud": null}` but the application specifies an expected audience argument,
    it raises MissingRequiredClaimError because the token does not contain a valid audience claim
    (since {"aud": null} should be treated as unspecified/missing).
    """
    payload = {"some": "payload", "aud": None}
    token = jwt_instance.encode(payload, "secret", algorithm="HS256")

    with pytest.raises(MissingRequiredClaimError) as exc_info:
        jwt_instance.decode(token, "secret", audience="urn:me", algorithms=["HS256"])

    assert exc_info.value.claim == "aud"


def test_decode_jwt_with_aud_null_and_verify_aud_false(jwt_instance):
    """
    Test that when verify_aud option is False, `{"aud": null}` is ignored successfully
    even if an audience argument is provided or not.
    """
    payload = {"some": "payload", "aud": None}
    token = jwt_instance.encode(payload, "secret", algorithm="HS256")

    decoded = jwt_instance.decode(
        token,
        "secret",
        algorithms=["HS256"],
        options={"verify_aud": False}
    )
    assert decoded == {"some": "payload", "aud": None}

import pytest
from jwt.api_jwt import PyJWT
from jwt.exceptions import (
    InvalidAudienceError,
    MissingRequiredClaimError,
)


@pytest.fixture
def jwt():
    return PyJWT()


class TestAudienceNullHandling:
    def test_decode_with_aud_null_and_no_audience_argument(self, jwt):
        # {"aud": null} with no audience argument provided should be ignored/treated as unspecified
        payload = {"some": "payload", "aud": None}
        token = jwt.encode(payload, "secret")

        # Should decode successfully without raising InvalidAudienceError
        decoded = jwt.decode(token, "secret", algorithms=["HS256"])
        assert decoded == payload

    def test_decode_with_aud_null_and_audience_argument_provided(self, jwt):
        # {"aud": null} when an audience argument is expected should raise MissingRequiredClaimError
        payload = {"some": "payload", "aud": None}
        token = jwt.encode(payload, "secret")

        with pytest.raises(MissingRequiredClaimError) as context:
            jwt.decode(token, "secret", audience="urn:me", algorithms=["HS256"])

        assert context.value.claim == "aud"
